import {STATIONS,CLASSES,berth} from './engine.js';
// Version 1-L byte-mode QR: 19 data codewords + 7 Reed–Solomon codewords.
export function qrMatrix(pnr){const text='DEMO:'+pnr;const bytes=new TextEncoder().encode(text);if(bytes.length>17)throw Error('Demo QR payload is too long.');const bits=[];const append=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>>i)&1);};append(4,4);append(bytes.length,8);bytes.forEach(b=>append(b,8));append(0,Math.min(4,152-bits.length));while(bits.length%8)bits.push(0);const data=[];for(let i=0;i<bits.length;i+=8)data.push(bits.slice(i,i+8).reduce((a,b)=>a*2+b,0));while(data.length<19)data.push(data.length%2=== (Math.ceil(bits.length/8)%2)?0xec:0x11);
 const mul=(x,y)=>{let z=0;for(let i=7;i>=0;i--){z=(z<<1)^((z>>>7)*0x11d);z^=((y>>>i)&1)*x;}return z;};const divisor=Array(7).fill(0);divisor[6]=1;let root=1;for(let i=0;i<7;i++){for(let j=0;j<7;j++){divisor[j]=mul(divisor[j],root);if(j+1<7)divisor[j]^=divisor[j+1];}root=mul(root,2);}const ecc=Array(7).fill(0);for(const d of data){const factor=d^ecc.shift();ecc.push(0);for(let i=0;i<7;i++)ecc[i]^=mul(divisor[i],factor);}const m=Array.from({length:21},()=>Array(21).fill(false)),fn=Array.from({length:21},()=>Array(21).fill(false));const set=(x,y,v)=>{if(x>=0&&x<21&&y>=0&&y<21){m[y][x]=!!v;fn[y][x]=true;}};for(let i=0;i<21;i++){set(6,i,i%2===0);set(i,6,i%2===0);}for(const [cx,cy]of [[3,3],[17,3],[3,17]])for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){const d=Math.max(Math.abs(dx),Math.abs(dy));set(cx+dx,cy+dy,d!==2&&d!==4);}const format=0x77c4;const bit=i=>((format>>>i)&1)!==0;for(let i=0;i<=5;i++)set(8,i,bit(i));set(8,7,bit(6));set(8,8,bit(7));set(7,8,bit(8));for(let i=9;i<15;i++)set(14-i,8,bit(i));for(let i=0;i<8;i++)set(20-i,8,bit(i));for(let i=8;i<15;i++)set(8,6+i,bit(i));set(8,13,true);const stream=data.concat(ecc).flatMap(n=>Array.from({length:8},(_,i)=>(n>>>(7-i))&1));let k=0;for(let right=20;right>=1;right-=2){if(right===6)right=5;for(let vert=0;vert<21;vert++){const y=((right+1)&2)===0?20-vert:vert;for(let j=0;j<2;j++){const x=right-j;if(!fn[y][x])m[y][x]=!!(stream[k++]^((x+y)%2===0?1:0));}}}return m;}
export function qrCanvas(pnr,size=232){const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,size,size);ctx.fillStyle='#153e36';const m=qrMatrix(pnr),cell=size/29;for(let y=0;y<21;y++)for(let x=0;x<21;x++)if(m[y][x])ctx.fillRect(Math.round((x+4)*cell),Math.round((y+4)*cell),Math.ceil(cell),Math.ceil(cell));return c;}
export const qrData=pnr=>qrCanvas(pnr).toDataURL('image/png');
export function ticketCanvas(b){const c=document.createElement('canvas');c.width=1240;c.height=1754;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);const text=(str,x,y,size=22,color='#153e36',bold=false,max)=>{ctx.fillStyle=color;ctx.font=`${bold?'bold ':''}${size}px Arial, sans-serif`;if(max)ctx.fillText(String(str),x,y,max);else ctx.fillText(String(str),x,y);};const line=(y)=>{ctx.strokeStyle='#dde5d7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(65,y);ctx.lineTo(1175,y);ctx.stroke();};ctx.fillStyle='#184f42';ctx.fillRect(0,0,1240,185);text('RailYatra',65,90,50,'#fff',true);text('EVERY JOURNEY MATTERS',65,133,17,'#cadac6');text('ELECTRONIC RESERVATION SLIP',695,78,21,'#fff',true);text('DEMO — NOT VALID FOR TRAVEL',695,115,19,'#edc692');text('PNR NUMBER',65,240,18,'#7d8d78');text(b.pnr,65,290,40,'#153e36',true);text(b.status+' · DEMO',860,275,25,b.status==='CANCELLED'?'#a24c44':'#4e7952',true);line(323);
const meta=(label,value,x,y,w=345)=>{text(label,x,y,16,'#7d8d78');text(value,x,y+35,21,'#153e36',true,w);};meta('TRAIN / NUMBER',`${b.trainName} (${b.trainId})`,65,365);meta('CLASS / QUOTA',`${CLASSES[b.cls].name} / ${b.quota}`,445,365);meta('BOOKED ON (IST)',new Date(b.bookedAt).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata'}),840,365);meta('FROM',`${STATIONS[b.from]} (${b.from})`,65,460);meta('TO',`${STATIONS[b.to]} (${b.to})`,445,460);meta('BOARDING POINT',`${STATIONS[b.boarding]} (${b.boarding})`,840,460);meta('DEPARTURE (IST)',`${b.departure.date} · ${b.departure.time}`,65,555);meta('ARRIVAL (IST)',`${b.arrival.date} · ${b.arrival.time}`,445,555);meta('BOARDING TIME (IST)',`${b.boardingTime.date} · ${b.boardingTime.time}`,840,555);ctx.fillStyle='#eef3e8';ctx.fillRect(65,645,1110,55);text('PASSENGER',80,680,17,'#68835e',true);text('AGE / GENDER',495,680,17,'#68835e',true);text('COACH / SEAT',735,680,17,'#68835e',true);text('STATUS',1060,680,17,'#68835e',true);let y=740;b.passengers.forEach((p,i)=>{text(`${i+1}. ${p.name}`,80,y,21,'#153e36',false,390);text(`${p.age} / ${p.gender}`,495,y,20);text(`${CLASSES[b.cls].coach} / ${b.seats[i]} · ${berth(b.seats[i])}`,735,y,18,'#153e36',false,295);text(b.status==='CONFIRMED'?'CNF':'CAN',1060,y,20,'#153e36',true);line(y+20);y+=62;});y+=45;text('FARE BREAKUP',65,y,19,'#153e36',true);y+=45;const rupees=n=>'INR '+Number(n).toLocaleString('en-IN');for(const [l,n]of [['Base fare',b.fare.base],['Reservation charge',b.fare.reservation],['Tatkal charge',b.fare.quotaCharge],['GST (simulated)',b.fare.tax],['Demo service fee',b.fare.service]]){text(l,65,y,21,'#7d8d78');text(rupees(n),405,y,21);y+=37;}text('TOTAL',65,y+15,25,'#153e36',true);text(rupees(b.fare.total),405,y+15,25,'#153e36',true);if(b.refund)text('Simulated refund: '+rupees(b.refund),65,y+55,20,'#996932');text('ALL PAYMENTS & BOOKINGS ARE SIMULATED',650,y-155,18,'#996932',true,515);const notes=['Independent RailYatra demo. No real money was charged.','Schedules, availability, fares and tracking are illustrative.','No live railway / IRCTC connection. Not an official ticket.','This ticket cannot be used to board a real train.'];notes.forEach((s,i)=>text(s,650,y-112+i*32,19,'#7d8d78',false,515));const footerY=1510;line(footerY);text('A journey worth taking.',65,footerY+55,26,'#153e36',true);text('Demo transaction: '+b.paymentId.slice(0,30),65,footerY+94,18,'#7d8d78');text('QR contains DEMO:'+b.pnr+' only.',65,footerY+126,18,'#7d8d78');text('It cannot verify a real railway reservation.',65,footerY+157,18,'#7d8d78');ctx.drawImage(qrCanvas(b.pnr,168),995,footerY+20,168,168);return c;}
function pdfFromCanvas(canvas){const jpeg=atob(canvas.toDataURL('image/jpeg',.92).split(',')[1]);const encode=s=>new TextEncoder().encode(s),chunks=[];let size=0;const offsets=[0];const push=b=>{chunks.push(b);size+=b.length;};const str=s=>push(encode(s));str('%PDF-1.4\n');const obj=(n,body)=>{offsets[n]=size;str(`${n} 0 obj\n${body}\nendobj\n`);};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>');offsets[4]=size;str(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);push(Uint8Array.from(jpeg,c=>c.charCodeAt(0)));str('\nendstream\nendobj\n');const content='q 595.28 0 0 841.89 0 0 cm /Im0 Do Q\n';obj(5,`<< /Length ${encode(content).length} >>\nstream\n${content}endstream`);const xref=size;str('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)str(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);str(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
export async function downloadTicket(b,format){const c=ticketCanvas(b);const blob=format==='pdf'?pdfFromCanvas(c):await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('Ticket export failed. Please retry.');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`RailYatra-DEMO-${b.pnr}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
